package gopatterns

import (
	"fmt"
	"go/ast"
	"reflect"
	"testing"

	"github.com/rstyled/gstyle/domain/pdg"
	"golang.org/x/tools/go/cfg"
)

// Expected call dependencies are written from the source, never generated by
// either CFG lowering or the postdominance implementation.
func TestControlSourceRegressions(t *testing.T) {
	cases := []struct {
		name, body string
		want       []string
	}{
		{"early return", `if a{return};work();after()`, []string{`if a{return}|2|work()`, `if a{return}|2|after()`}},
		{"join", `if a{work()};after()`, []string{`if a{work()}|1|work()`}},
		{"continue", `for a{if b{continue};work()};after()`, []string{`if b{continue}|2|work()`, `for a{if b{continue};work()}|2|after()`}},
		{"break", `for{if a{break};work()};after()`, []string{`if a{break}|2|work()`, `if a{break}|1|after()`}},
		{"goto", `if a{goto done};work();done:after()`, []string{`if a{goto done}|2|work()`}},
		{"backward goto", `again:if a{work();goto again};after()`, []string{`if a{work();goto again}|1|work()`, `if a{work();goto again}|2|after()`}},
		{"constant false", `for false{work()};after()`, nil},
		{"constant true", `for true{if a{break};work()};after()`, []string{`if a{break}|2|work()`, `if a{break}|1|after()`}},
		{"unavoidable cycle", `for{one();two()}`, []string{`one()|1|one()`, `two()|1|two()`}},
		{"short and", `if a&&predicate(){work()};after()`, []string{`a|1|predicate()`, `if a&&predicate(){work()}|1|work()`}},
		{"short or", `if a||predicate(){work()};after()`, []string{`a|2|predicate()`, `if a||predicate(){work()}|1|work()`}},
		{"tagless switch", `switch{case false:one();default:work()};after()`, nil},
		{"type switch", `var value any=x;switch value.(type){case int:one();default:two()};after()`, []string{`case int:one()|1|one()`, `case int:one()|2|two()`}},
		{"labelled break", `outer:for{for{if a{break outer};work()}};after()`, []string{`if a{break outer}|2|work()`, `if a{break outer}|1|after()`}},
		{"range", `for range []int{1,2}{work()};after()`, []string{`for range []int{1,2}{work()}|1|work()`, `for range []int{1,2}{work()}|2|after()`}},
		{"skipped rhs", `if false&&predicate(){work()};after()`, nil},
		{"panic", `if a{panic("stop")};work()`, []string{`if a{panic("stop")}|1|panic("stop")`, `if a{panic("stop")}|2|work()`}},
		{"switch", `switch x{case 1:one();case 2:two();default:work()};after()`, []string{`case 1:one()|1|one()`, `case 2:two()|1|two()`, `case 2:two()|2|work()`}},
		{"fallthrough", `switch x{case 1:one();fallthrough;case 2:two();default:work()};after()`, []string{`case 1:one();fallthrough|1|one()`, `case 1:one();fallthrough|1|two()`, `case 2:two()|1|two()`, `case 2:two()|2|work()`}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			source := `package p;func f(a,b bool,x int){` + tc.body + `};func work(){};func after(){};func one(){};func two(){};func predicate()bool{return true}`
			graph := parseIR(t, source, pdg.NewBuilder())
			if err := pdg.Validate(&graph); err != nil {
				t.Fatal(err)
			}
			got, want := controlCallEdges(graph, source), map[string]bool{}
			for _, edge := range tc.want {
				want[edge] = true
			}
			if !reflect.DeepEqual(got, want) {
				t.Fatalf("call control got %v,want %v", got, want)
			}
		})
	}
}

func controlCallEdges(graph pdg.Graph, source string) map[string]bool {
	out := map[string]bool{}
	for _, edge := range graph.Edges {
		if edge.Kind != pdg.ControlEdge || graph.Nodes[edge.Target-1].Category != pdg.Call {
			continue
		}
		from, to := graph.Nodes[edge.Source-1], graph.Nodes[edge.Target-1]
		a, z := graph.Spans[from.Span-1], graph.Spans[to.Span-1]
		out[fmt.Sprintf("%s|%d|%s", source[a.Start:a.End], edge.Position, source[z.Start:z.End])] = true
	}
	return out
}

func TestResolvedNonReturningCalls(t *testing.T) {
	for _, tc := range []struct {
		imports, call string
		terminal      bool
	}{
		{`import "os";`, `os.Exit(1)`, true},
		{`import "runtime";`, `runtime.Goexit()`, true},
		{`import "log";`, `log.Fatal("stop")`, true},
		{`import "log";`, `log.Panic("stop")`, true},
		{``, `Fatal("stop")`, false},
		{``, `Exit(1)`, false},
	} {
		source := `package p;` + tc.imports + `func f(a bool){if a{` + tc.call + `};work()};func Exit(int){};func Fatal(string){};func work(){}`
		graph := parseIR(t, source, pdg.NewBuilder())
		got := controlCallEdges(graph, source)
		key := `if a{` + tc.call + `}|2|work()`
		if got[key] != tc.terminal {
			t.Fatalf("%s work dependency=%v,want %v", tc.call, got, tc.terminal)
		}
	}
}

func TestTransfersRemainSourceOperations(t *testing.T) {
	source := `package p;func f(a bool){for{if a{break};continue}}`
	graph := parseIR(t, source, pdg.NewBuilder())
	want := map[string]pdg.Position{"break": 1, "continue": 2}
	for _, edge := range graph.Edges {
		if edge.Kind != pdg.ControlEdge {
			continue
		}
		span := graph.Spans[graph.Nodes[edge.Target-1].Span-1]
		text := source[span.Start:span.End]
		if outcome, ok := want[text]; ok {
			if outcome != edge.Position {
				t.Fatalf("%s controlled by %d,want %d", text, edge.Position, outcome)
			}
			delete(want, text)
		}
	}
	if len(want) != 0 {
		t.Fatalf("missing transfer dependencies: %v", want)
	}
}

func TestControlResourceFailureIsExplicit(t *testing.T) {
	flow := &cfg.CFG{Blocks: make([]*cfg.Block, controlVertexLimit+1)}
	for index := range flow.Blocks {
		flow.Blocks[index] = &cfg.Block{Index: int32(index)}
	}
	builder := &irBuilder{pool: pdg.NewBuilder()}
	if err := builder.semanticControlFor(&ast.BlockStmt{}, flow); err == nil {
		t.Fatal("resource limit silently treated as successful analysis")
	}
}

func BenchmarkMaximalPostDominators(b *testing.B) {
	for _, size := range []int{64, 256, 1024} {
		flow := &cfg.CFG{Blocks: make([]*cfg.Block, size)}
		for index := range flow.Blocks {
			flow.Blocks[index] = &cfg.Block{Index: int32(index)}
		}
		for index := 0; index < size-1; index++ {
			flow.Blocks[index].Succs = []*cfg.Block{flow.Blocks[index+1]}
		}
		flow.Blocks[size-1].Succs = []*cfg.Block{flow.Blocks[0], flow.Blocks[size/2]}
		dom := newExecutionDominators(flow)
		b.Run(fmt.Sprint(size), func(b *testing.B) {
			for b.Loop() {
				maximalPostDominators(flow, dom)
			}
		})
	}
}

func TestControlLoweringIsIndependentOfValueFlow(t *testing.T) {
	for _, source := range []string{
		`package p;func f(x string)string{if false{return "dead"};return x}`,
		`package p;func f(xs []*int){for _,x:=range xs{if x!=nil{work(*x)}}};func work(int){}`,
		`package p;func f(a bool,p *int){if a&&p!=nil{work(*p)}};func work(int){}`,
	} {
		graph := parseIR(t, source, pdg.NewBuilder())
		if err := pdg.Validate(&graph); err != nil {
			t.Fatal(err)
		}
		seen := map[[3]pdg.Ref]bool{}
		for _, edge := range graph.Edges {
			if edge.Kind != pdg.ControlEdge {
				continue
			}
			key := [3]pdg.Ref{edge.Source, edge.Target, pdg.Ref(edge.Position)}
			if seen[key] {
				t.Fatalf("duplicate control occurrence %v", key)
			}
			seen[key] = true
			span := graph.Spans[graph.Nodes[edge.Target-1].Span-1]
			if source[span.Start:span.End] == `return "dead"` {
				t.Fatal("value-flow lowering concealed constant source condition")
			}
		}
	}
}
